mapper.select:
        SELECT * FROM (
           SELECT b.id AS billingId,a.id AS billingImgsId,b.case_no AS caseNo,b.case_title AS caseTitle,b.billing_enum AS billingEnum,
            b.billing_item AS billingItem,a.billing_code AS billingCode,a.billing_money AS billingMoney,b.company_name AS companyName,a.create_time AS createTime,
            b.org_name AS orgName,b.staff_org_name AS staffOrgName,IFNULL(SUM(c.money),0) AS theAccountMoney
            FROM  billing_apply_imgs a
            LEFT JOIN billing_apply b ON a.bill_id=b.id
            LEFT JOIN billing_apply_accounts c ON a.id=c.bill_imgs_id and c.state = 1
            where b.billing_enum !=7 and b.billing_state = #{billingState,jdbcType=INTEGER}
--             and (b.confirm_account_state = 1 or b.confirm_account_state = 3)
             AND a.state = 1

                and b.case_no=#{caseNo}


                and b.case_title=#{caseTitle}


                and a.billing_code=#{billingCode}


                and b.create_by_id = #{currentUserId}

            GROUP BY a.id
        ) aa WHERE aa.billingMoney > aa.theAccountMoney
        order by aa.createTime desc

select

from billing_apply
where 1 = 1

    and case_id = #{caseId,jdbcType=BIGINT}


    and is_pre_sign = #{isPreSign,jdbcType=BIGINT}


    and case_no = #{caseNo,jdbcType=VARCHAR}

 limit 1

select

from billing_apply b
where 1 = 1 and b.billing_state = 1 and b.parent_id is null and b.is_merge is null

    and b.company_id = #{companyId,jdbcType=BIGINT}


    and b.billing_type = #{billingType,jdbcType=INTEGER}


    and b.business_type = #{businessType,jdbcType=INTEGER}


    and b.org_id = #{orgId,jdbcType=BIGINT}


    and b.create_by_id = #{currentUserId,jdbcType=BIGINT}

if.foreach:
SELECT tabA.*,tabB.accMoney as accMoney,tabC.unmatchMoney,#{item.months} dateTime FROM (
SELECT e.enum_code enumCode,e.enum_name enumName, IFNULL(b.imgMoney,0) as imgMoney FROM ( select * from (SELECT b.id,b.enum_code,b.enum_name from common_enum b where b.parent_id = (SELECT a.id from common_enum a where a.enum_code = 'billingEnum') UNION ALL SELECT -2 id,-2 enum_code, CONCAT(#{item.months},'开票总金额') as enum_name UNION ALL SELECT 99999 id,99999 enum_code,CONCAT(#{item.months},'应收账款余额') as enum_name UNION ALL SELECT -1 id,-1 enum_code, CONCAT(#{item.months},'到账总金额') as enum_name) a
where FIND_IN_SET(a.enum_code,#{enumCode})
) e left join ( select SUM(IFNULL(i.billing_money, 0)) imgMoney,a.billing_enum as billing_enum from billing_apply a LEFT JOIN billing_apply_imgs i ON a.id = i.bill_id where DATE_FORMAT(i.create_time,'%Y-%m') = #{item.months} AND a.org_id = #{orgId} and find_in_set(a.business_type,#{businessType,jdbcType=VARCHAR}) GROUP BY a.billing_enum )b on b.billing_enum= e.enum_code
GROUP BY e.enum_code ORDER BY cast(e.enum_code as SIGNED INTEGER) ) tabA LEFT JOIN ( SELECT e.enum_code enumCode,e.enum_name enumName,SUM(IFNULL(a.unmatch_money,0)) unmatchMoney FROM ( SELECT b.id,b.enum_code,b.enum_name from common_enum b where b.parent_id = (SELECT a.id from common_enum a where a.enum_code = 'billingEnum')
AND FIND_IN_SET(b.enum_code,#{enumCode})
) e LEFT JOIN billing_apply_unmatch a ON e.id = a.billing_items_id AND DATE_FORMAT(a.pay_time,'%Y-%m') = #{item.months}
GROUP BY e.enum_code ) tabC ON tabA.enumCode = tabC.enumCode LEFT JOIN ( SELECT e.enum_code enumCode,e.enum_name enumName, IFNULL(b.accMoney,0) as accMoney FROM ( select * from (SELECT b.id,b.enum_code,b.enum_name from common_enum b where b.parent_id = (SELECT a.id from common_enum a where a.enum_code = 'billingEnum') UNION ALL SELECT -2 id,-2 enum_code, CONCAT(#{item.months},'开票总金额') as enum_name UNION ALL SELECT 99999 id,99999 enum_code,CONCAT(#{item.months},'应收账款余额') as enum_name UNION ALL SELECT -1 id,-1 enum_code, CONCAT(#{item.months},'到账总金额') as enum_name) a
where FIND_IN_SET(a.enum_code,#{enumCode})
) e left join ( select SUM(IFNULL(s.money, 0)) accMoney, a.billing_enum as billing_enum from billing_apply a LEFT JOIN billing_apply_accounts s ON a.id = s.bill_id where DATE_FORMAT(s.account_time,'%Y-%m') = #{item.months} AND a.org_id = #{orgId} and find_in_set(a.business_type,#{businessType,jdbcType=VARCHAR}) GROUP BY a.billing_enum )b on b.billing_enum= e.enum_code GROUP BY e.enum_code ORDER BY cast(e.enum_code as SIGNED INTEGER) ) tabB on tabA.enumCode = tabB.enumCode
union all

select.if:
SELECT e.enum_code enumCode,e.enum_name enumName,SUM(IFNULL(i.money,0)) accMoney,SUM(IFNULL(s.billing_money,0)) imgMoney FROM ( select * from (SELECT b.id,b.enum_code,b.enum_name from common_enum b where b.parent_id = (SELECT a.id from common_enum a where a.enum_code = 'billingEnum') UNION ALL SELECT -2 id,-2 enum_code,CONCAT(#{item.months},'开票总金额') as enum_name UNION ALL SELECT -1 id,-1 enum_code,CONCAT(#{item.months},'到账总金额') as enum_name) a
where FIND_IN_SET(a.enum_code,#{enumCode})
) e LEFT JOIN billing_apply a ON e.enum_code = a.billing_enum AND a.org_id = #{orgId}
and a.business_type = #{businessTypeId,jdbcType=BIGINT}
left join billing_apply_imgs s on a.id = s.bill_id AND DATE_FORMAT(s.create_time,'%Y') = '2020' LEFT JOIN billing_apply_accounts i ON a.id = i.bill_id AND DATE_FORMAT(i.account_time,'%Y') = '2020'
GROUP BY e.enum_code ORDER BY cast(e.enum_code as SIGNED INTEGER)
